import sys

def solve():
    input = sys.stdin.read().split()
    idx = 0

    T = int(input[idx])
    idx += 1

    results = []

    for _ in range(T):
        n = int(input[idx])
        idx += 1

        adj = [[] for _ in range(n + 1)]
        for _ in range(n - 1):
            u = int(input[idx])
            v = int(input[idx + 1])
            idx += 2
            adj[u].append(v)
            adj[v].append(u)

        colored_str = input[idx]
        idx += 1

        colored = [False] * (n + 1)
        for i, c in enumerate(colored_str):
            if c == 'W':
                colored[i + 1] = True

        has_winning_white = False
        for v in range(1, n + 1):
            if colored[v]:
                cnt = 0
                for u in adj[v]:
                    if colored[u]:
                        cnt += 1
                if cnt >= 2:
                    has_winning_white = True
                    break

        if has_winning_white:
            results.append("White")
            continue

        white_can_win = False

        for v in range(1, n + 1):
            degree = len(adj[v])
            if degree < 2:
                continue

            w_neighbors = 0
            for u in adj[v]:
                if colored[u]:
                    w_neighbors += 1

            if w_neighbors >= 2:
                pass
            elif w_neighbors == 1:
                if not colored[v]:
                    white_can_win = True
                    break
            elif w_neighbors == 0:
                if not colored[v] and degree >= 2:
                    white_can_win = True
                    break

        if white_can_win:
            results.append("White")
        else:
            results.append("Draw")

    print('\n'.join(results))

if __name__ == "__main__":
    solve()
